package com.wealthflow;
import jakarta.persistence.*;import java.time.Instant;import java.math.BigDecimal;
@Entity @Table(name="workflow_state",uniqueConstraints=@UniqueConstraint(name="uk_workflow_event_id",columnNames="event_id"))
public class WorkflowState {@Id @Column(name="chargeback_id",nullable=false) private String chargebackId;@Column(name="event_id",nullable=false) private String eventId;@Column(name="owner_id",nullable=false) private String ownerId;@Column(nullable=false) private String status;@Column(nullable=false,precision=19,scale=2) private BigDecimal totalBilledAmount;@Column(nullable=false,precision=19,scale=2) private BigDecimal finalAllocatedAmount;private String rateVersion;@Column(nullable=false) private Instant finalizedAt;protected WorkflowState(){}public WorkflowState(ChargebackEvent e){chargebackId=e.chargebackId();eventId=e.eventId();ownerId=e.ownerId();status="FINALIZED";totalBilledAmount=e.totalBilledAmount();finalAllocatedAmount=e.finalAllocatedAmount();rateVersion=e.rateVersion();finalizedAt=e.finalizedAt();}public String getChargebackId(){return chargebackId;}public String getEventId(){return eventId;}public String getOwnerId(){return ownerId;}public String getStatus(){return status;}public BigDecimal getTotalBilledAmount(){return totalBilledAmount;}public BigDecimal getFinalAllocatedAmount(){return finalAllocatedAmount;}public String getRateVersion(){return rateVersion;}public Instant getFinalizedAt(){return finalizedAt;}}
